ALTER TABLE public.materials ADD COLUMN IF NOT EXISTS content text, ADD COLUMN IF NOT EXISTS unit_code text, ADD COLUMN IF NOT EXISTS level text;
DELETE FROM public.materials WHERE external_url IS NOT NULL AND file_path IS NULL;
INSERT INTO public.materials (title, description, subject, material_type, course, unit_code, level)
SELECT t, 'Core unit in '||p||' as taught in Kenyan '||CASE l WHEN 'University' THEN 'universities' WHEN 'College' THEN 'colleges and TVET institutions' ELSE 'professional exams' END||'. Full notes read inside Franky''s.', s, 'Unit', p, a||' '||lpad((100*((n-1)/5+1)+n)::text,3,'0'), l FROM (
SELECT 'Bachelor of Science in Computer Science' p,'Computer Science' s,'University' l,'CS' a,x.t,x.n FROM unnest(ARRAY['Introduction to Computer Science','Programming Methodology (C)','Discrete Mathematics','Data Structures and Algorithms','Object Oriented Programming (Java)','Database Systems','Operating Systems','Computer Networks','Software Engineering','Computer Architecture','Theory of Computation','Artificial Intelligence','Web Application Development','Mobile Application Development','Information Security','Compiler Construction','Human Computer Interaction','Distributed Systems','Machine Learning','Computer Graphics']) WITH ORDINALITY x(t,n)
UNION ALL SELECT 'Bachelor of Science in Information Technology','Information Technology','University','IT',x.t,x.n FROM unnest(ARRAY['Fundamentals of IT','Systems Analysis and Design','Network Administration','Cloud Computing','IT Project Management','E-Commerce','Management Information Systems','Cyber Security Fundamentals']) WITH ORDINALITY x(t,n)
UNION ALL SELECT 'Bachelor of Commerce','Business','University','BCOM',x.t,x.n FROM unnest(ARRAY['Principles of Management','Financial Accounting I','Financial Accounting II','Microeconomics','Macroeconomics','Business Mathematics','Business Statistics','Principles of Marketing','Business Law','Cost Accounting','Management Accounting','Financial Management','Human Resource Management','Organisational Behaviour','Entrepreneurship and Innovation','Auditing and Assurance','Taxation','Strategic Management','Operations Management','Banking and Finance']) WITH ORDINALITY x(t,n)
UNION ALL SELECT 'Bachelor of Education (Arts)','Education','University','EDU',x.t,x.n FROM unnest(ARRAY['Foundations of Education','Educational Psychology','Curriculum Development','Philosophy of Education','Sociology of Education','Educational Administration and Planning','Guidance and Counselling','Research Methods in Education','Instructional Methods','Measurement and Evaluation','Special Needs Education','History of Education in Kenya']) WITH ORDINALITY x(t,n)
UNION ALL SELECT 'Bachelor of Education (Science)','Education','University','EDS',x.t,x.n FROM unnest(ARRAY['Teaching Methods in Mathematics','Teaching Methods in Biology','Teaching Methods in Chemistry','Teaching Methods in Physics','Educational Technology']) WITH ORDINALITY x(t,n)
UNION ALL SELECT 'Bachelor of Laws (LLB)','Law','University','LAW',x.t,x.n FROM unnest(ARRAY['Legal Systems and Methods','Law of Contract','Law of Torts','Constitutional Law of Kenya','Criminal Law','Family Law and Succession','Land Law','Law of Evidence','Commercial Law','Administrative Law','Jurisprudence','Public International Law','Company Law','Civil Procedure','Human Rights Law','Labour Law']) WITH ORDINALITY x(t,n)
UNION ALL SELECT 'Bachelor of Medicine and Bachelor of Surgery (MBChB)','Medicine','University','MED',x.t,x.n FROM unnest(ARRAY['Human Anatomy','Medical Physiology','Medical Biochemistry','Histology and Embryology','Medical Microbiology','Pathology','Pharmacology','Internal Medicine','General Surgery','Paediatrics and Child Health','Obstetrics and Gynaecology','Community Health and Epidemiology','Psychiatry']) WITH ORDINALITY x(t,n)
