UNION ALL SELECT 'Bachelor of Science in Civil Engineering','Engineering','University','ECE',x.t,x.n FROM unnest(ARRAY['Engineering Mathematics I','Engineering Mathematics II','Engineering Drawing','Strength of Materials','Fluid Mechanics','Surveying','Structural Analysis','Soil Mechanics','Reinforced Concrete Design','Highway Engineering','Hydraulics and Hydrology','Construction Management']) WITH ORDINALITY x(t,n)
