UNION ALL SELECT 'Bachelor of Science in Agriculture','Agriculture','University','AGR',x.t,x.n FROM unnest(ARRAY['Introduction to Agriculture','Crop Production','Soil Science','Animal Production','Agricultural Economics','Plant Pathology','Agricultural Extension','Farm Management','Agronomy','Horticulture']) WITH ORDINALITY x(t,n)
