UNION ALL SELECT 'Bachelor of Science (Physical and Biological Sciences)','Sciences','University','SCI',x.t,x.n FROM unnest(ARRAY['General Biology','Cell Biology','Genetics','Ecology','Botany','Zoology','General Chemistry','Organic Chemistry','Inorganic Chemistry','Physical Chemistry','Mechanics','Electricity and Magnetism','Modern Physics','Optics and Waves']) WITH ORDINALITY x(t,n)
