UNION ALL SELECT 'CPA (KASNEB)','Accounting','Professional','CPA',x.t,x.n FROM unnest(ARRAY['Financial Accounting','Introduction to Law and Governance','Economics','Quantitative Analysis','Public Finance and Taxation','Management Accounting','Financial Reporting','Auditing and Assurance','Advanced Financial Reporting','Advanced Management Accounting','Strategy, Governance and Ethics','Leadership and Management']) WITH ORDINALITY x(t,n)
