UNION ALL SELECT 'Diploma in Information Communication Technology (KNEC/CDACC)','ICT (TVET)','College','DICT',x.t,x.n FROM unnest(ARRAY['Computer Applications','Introduction to Programming','Database Management','Web Design','Computer Maintenance and Repair','Networking Essentials','Structured Programming','Visual Programming','System Analysis and Design','Operating Systems Management']) WITH ORDINALITY x(t,n)
UNION ALL SELECT 'Diploma in Business Management (KNEC)','Business (TVET)','College','DBM',x.t,x.n FROM unnest(ARRAY['Business Communication','Principles of Management','Office Administration','Business Calculations and Statistics','Purchasing and Supply','Sales and Marketing','Entrepreneurship Education','Human Resource Management','Commerce','Book-keeping and Accounts']) WITH ORDINALITY x(t,n)
