UNION ALL SELECT 'Diploma in Mechanical and Automotive Engineering','Engineering (TVET)','College','DAE',x.t,x.n FROM unnest(ARRAY['Motor Vehicle Technology','Engine Systems','Vehicle Electrical Systems','Fitting and Machining','Welding and Fabrication']) WITH ORDINALITY x(t,n)
UNION ALL SELECT 'Diploma in Building and Civil Engineering','Engineering (TVET)','College','DBC',x.t,x.n FROM unnest(ARRAY['Building Construction','Plumbing','Quantity Surveying','Land Surveying','Building Materials']) WITH ORDINALITY x(t,n)
UNION ALL SELECT 'Diploma in Clinical Medicine (KMTC)','Health (TVET)','College','DCM',x.t,x.n FROM unnest(ARRAY['Clinical Methods','Anatomy for Clinical Officers','Physiology','Medicine','Surgery','Reproductive Health']) WITH ORDINALITY x(t,n)
UNION ALL SELECT 'Diploma in Kenya Registered Community Health Nursing (KMTC)','Health (TVET)','College','KRCHN',x.t,x.n FROM unnest(ARRAY['Foundations of Nursing','Midwifery','Community Health','Nutrition and Dietetics','Health Records and Information']) WITH ORDINALITY x(t,n)
UNION ALL SELECT 'Diploma in Early Childhood Development Education','Education (TVET)','College','ECDE',x.t,x.n FROM unnest(ARRAY['Child Development and Psychology','ECDE Curriculum','Play and Learning','Early Literacy and Numeracy','Health and Nutrition in ECDE']) WITH ORDINALITY x(t,n)
UNION ALL SELECT 'Diploma in Primary Teacher Education (DPTE)','Education (TVET)','College','DPTE',x.t,x.n FROM unnest(ARRAY['Professional Studies','CBC Pedagogy','Teaching of English','Teaching of Kiswahili','Teaching of Mathematics','Teaching of Science and Technology']) WITH ORDINALITY x(t,n)
UNION ALL SELECT 'Diploma in Food and Beverage / Catering','Hospitality (TVET)','College','DFB',x.t,x.n FROM unnest(ARRAY['Food Production','Food and Beverage Service','Food Safety and Hygiene','Nutrition','Pastry and Bakery']) WITH ORDINALITY x(t,n)
UNION ALL SELECT 'Certificate/Diploma in Fashion Design and Hair Dressing','Creative (TVET)','College','DFD',x.t,x.n FROM unnest(ARRAY['Garment Construction','Fashion Illustration','Textile Science','Hairdressing and Beauty Therapy']) WITH ORDINALITY x(t,n)
UNION ALL SELECT 'Diploma in Supply Chain Management (KISM)','Business (TVET)','College','DSCM',x.t,x.n FROM unnest(ARRAY['Principles of Procurement','Logistics and Transport','Stores Management','Public Procurement and Disposal Act']) WITH ORDINALITY x(t,n)
UNION ALL SELECT 'Diploma in Agriculture (TVET)','Agriculture (TVET)','College','DAG',x.t,x.n FROM unnest(ARRAY['Crop Husbandry','Livestock Production','Agricultural Engineering','Farm Records and Accounts','Agribusiness']) WITH ORDINALITY x(t,n)
) z;
CREATE TABLE public.chat_conversations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  title text NOT NULL DEFAULT 'New chat',
  messages jsonb NOT NULL DEFAULT '[]'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.chat_conversations TO authenticated;
GRANT ALL ON public.chat_conversations TO service_role;
ALTER TABLE public.chat_conversations ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Users manage own conversations" ON public.chat_conversations FOR ALL TO authenticated USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);
CREATE INDEX chat_conversations_user_idx ON public.chat_conversations(user_id, updated_at DESC);
CREATE TRIGGER chat_conversations_updated_at BEFORE UPDATE ON public.chat_conversations FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();